```js
function twoSum(values, target) {
  const seen = new Map();
  for (let i = 0; i < values.length; i++) {
    const need = target - values[i];
    if (seen.has(need)) return [seen.get(need), i];
    seen.set(values[i], i);
  }
  return null;
}
```

The Map contains only indices visited before the current index.

```js
function frequencies(text) {
  const count = new Map();
  for (const ch of text) {
    count.set(ch, (count.get(ch) ?? 0) + 1);
  }
  return count;
}
```

`frequencies('banana').get('a')` is `3`.

```js
function groupAnagrams(words) {
  const groups = new Map();
  for (const word of words) {
    const key = [...word].sort().join('');
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(word);
  }
  return [...groups.values()];
}
```

Each original word is stored under its order-independent signature.

```js
function longestConsecutive(values) {
  const set = new Set(values);
  let best = 0;
  for (const value of set) {
    if (set.has(value - 1)) continue;
    let length = 1;
    while (set.has(value + length)) length++;
    best = Math.max(best, length);
  }
  return best;
}
```

Only values with no predecessor start a counting loop.
